import{r,j as e}from"./vendor-DvrhTn1k.js";function i(){return r.useEffect(()=>{window.scrollTo(0,0)},[]),e.jsx("div",{className:"min-h-screen bg-white py-12 px-4 sm:px-6 lg:px-8",children:e.jsxs("div",{className:"max-w-4xl mx-auto",children:[e.jsx("h1",{className:"text-4xl font-bold text-gray-900 mb-2",children:"MANAS360 - Data Processing Agreement (DPA)"}),e.jsx("p",{className:"text-sm text-gray-600 mb-1",children:"Compliant with DPDPA 2023"}),e.jsx("p",{className:"text-sm text-gray-600 mb-8",children:"Between: MANAS360 Private Limited (Data Fiduciary) and Provider (Data Processor)"}),e.jsxs("div",{className:"prose prose-lg max-w-none",children:[e.jsx("h2",{children:"1. DEFINITIONS"}),e.jsx("p",{children:'1.1 "Data Fiduciary" shall have the meaning assigned under the Digital Personal Data Protection Act, 2023 ("DPDP Act") and refers to MANAS360, which determines the purpose and means of processing personal data.'}),e.jsx("p",{children:'1.2 "Data Processor" means the Provider, who processes personal data on behalf of the Data Fiduciary in the course of providing therapeutic services.'}),e.jsx("p",{children:'1.3 "Personal Data" means any data about an individual who is identifiable, including health data, as defined under DPDPA 2023.'}),e.jsx("p",{children:'1.4 "Processing" includes collection, recording, storage, organization, structuring, use, sharing, disclosure, restriction, erasure, or destruction of Personal Data.'}),e.jsx("h2",{children:"2. SCOPE"}),e.jsx("p",{children:"2.1 This DPA governs the Provider's processing of patient personal data accessed through the MANAS360 Platform."}),e.jsx("h2",{children:"3. PROCESSING OBLIGATIONS"}),e.jsx("p",{children:"3.1 The Provider shall process patient data ONLY for the purpose of providing mental health services through the Platform."}),e.jsx("p",{children:"3.2 The Provider shall not process patient data for any other purpose, including personal research, marketing, or sharing with third parties."}),e.jsx("p",{children:"3.3 The Provider shall implement reasonable security safeguards as specified in MANAS360's Security Policy, including: (a) using a secure, password-protected device; (b) enabling 2-factor authentication; (c) not accessing patient data on shared or public computers; (d) conducting sessions from a private, sound-proof location."}),e.jsx("p",{children:"3.4 The Provider shall adhere to the principle of data minimization by accessing only such Personal Data as is strictly necessary for providing services to patients formally assigned to them through the Platform. The Provider shall not attempt to access, view, retrieve, or manipulate personal or clinical data relating to patients who are not under their authorized care or clinical responsibility. The Provider is strictly prohibited from downloading, exporting, copying, transferring, or storing any Personal Data outside the Platform's secure environment unless such action is expressly permitted in writing by MANAS360 or is otherwise required under applicable law."}),e.jsx("h2",{children:"4. SUB-PROCESSING"}),e.jsx("p",{children:"4.1 The Provider shall not appoint or engage any sub-processor to process patient data without prior written consent from MANAS360."}),e.jsx("h2",{children:"5. DATA BREACH"}),e.jsx("p",{children:"5.1 The Provider shall notify MANAS360 of any suspected or actual personal data breach within 12 hours of becoming aware."}),e.jsx("p",{children:"5.2 Notification shall include: nature of breach, categories of data affected, number of individuals affected, and remedial measures taken."}),e.jsx("p",{children:"5.3 The Provider shall be solely liable for any losses, damages, penalties, regulatory fines, or other adverse consequences arising out of or in connection with unauthorized or unlawful processing of personal data, negligent or improper handling of Personal Data, failure to implement required technical or organizational security safeguards, or delay or failure in providing mandatory breach notification as required under applicable law."}),e.jsx("h2",{children:"6. DATA SUBJECT REQUESTS"}),e.jsx("p",{children:"6.1 If a patient contacts the Provider directly to exercise their DPDPA rights (access, correction, erasure), the Provider shall forward the request to MANAS360 within 24 hours. The Provider shall assist MANAS360 in fulfilling statutory obligations relating to data subject rights."}),e.jsx("h2",{children:"7. RETURN AND DELETION"}),e.jsx("p",{children:"7.1 Upon termination, the Provider shall cease all processing and confirm in writing that no patient data is retained on personal devices or systems."}),e.jsx("h2",{children:"8. AUDIT"}),e.jsx("p",{children:"8.1 MANAS360 reserves the right to conduct data protection audits (no more than once per quarter with 7 days' notice) to verify compliance. The Provider shall cooperate fully and provide reasonable access to relevant documentation demonstrating compliance."}),e.jsx("h2",{children:"9. GOVERNING LAW"}),e.jsx("p",{children:"9.1 This Agreement shall be governed by and construed in accordance with the laws of India. Any dispute, controversy, or claim arising out of or in connection with this Agreement shall be referred to and finally resolved by arbitration in accordance with the Arbitration and Conciliation Act, 1996, as amended from time to time. The seat and venue of arbitration shall be Bengaluru, Karnataka, India, and the arbitral proceedings shall be conducted in the English language."})]})]})})}export{i as default};
